import { tags } from "typia";

/**
 * Optional filter criteria applied to payment transactions before aggregating
 * funnel metrics.
 *
 * These filters operate on payment-level attributes such as payment method,
 * currency, provider, or risk flags. They are evaluated after joining orders to
 * payment transactions but before computing aggregated counts and monetary
 * totals per funnel stage.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallPaymentFunnelPaymentFilter = {
  /**
   * Optional list of payment method codes to include in the analytics.
   *
   * Only payment transactions whose method is in this list are considered
   * in-scope. Examples might include `card`, `bank_transfer`, `wallet`, or
   * integration-specific method identifiers.
   */
  paymentMethodCodes?: string[] | undefined;

  /**
   * Optional list of three-letter ISO 4217 currency codes to include.
   *
   * When provided, only payment transactions whose currency matches one of
   * the specified codes are included in the analytics. This allows focusing
   * on specific reporting currencies or regions.
   */
  currencyCodes?:
    | (string & tags.MinLength<3> & tags.MaxLength<3>)[]
    | undefined;

  /**
   * Optional list of payment provider identifiers to filter transactions by
   * processor or gateway.
   *
   * Typical values might correspond to PSP names, acquiring banks, or
   * internal routing keys used in the payment stack.
   */
  providerCodes?: string[] | undefined;

  /**
   * When true, restrict analytics to payment transactions that have been
   * flagged by risk or fraud systems.
   *
   * This allows analysts to compute funnel behavior specifically for
   * high-risk cohorts, for example to evaluate additional friction or control
   * strategies. When false or omitted, both flagged and unflagged
   * transactions are included.
   */
  includeRiskFlaggedOnly?: boolean | undefined;
};
